function drawCoverCrop(ctx,image,rect,crop){const scale=Math.max(rect.width/image.naturalWidth,rect.height/image.naturalHeight)*crop.zoom,sourceWidth=rect.width/scale,sourceHeight=rect.height/scale,sx=(image.naturalWidth-sourceWidth)*(crop.x/100),sy=(image.naturalHeight-sourceHeight)*(crop.y/100);ctx.drawImage(image,Math.max(0,sx),Math.max(0,sy),Math.min(image.naturalWidth,sourceWidth),Math.min(image.naturalHeight,sourceHeight),rect.x,rect.y,rect.width,rect.height)}
function canvasTextFont(fontSize,bold=false,italic=false){return`${italic?'italic ':''}${bold?'700':'400'} ${fontSize}px "Microsoft YaHei",sans-serif`}
