function renderArtCandidates(){const box=q('#cardArtCandidates'),items=artAssets.filter(x=>x.provenance!=='user_reference'&&(!activeCardId||x.cardId===activeCardId));box.replaceChildren(...items.map(asset=>{const button=document.createElement('button'),image=document.createElement('img');button.type='button';button.className=`art-candidate${asset.id===selectedArtAssetId?' selected':''}`;button.title=`选中并查看 · ${asset.provider||asset.model} · ${asset.size}`;image.src=artFileUrl(asset.id);image.alt='AI 候选卡面';button.append(image);button.onclick=()=>{selectedArtAssetId=asset.id;renderCardArt();openImageViewer(asset,q('#cardName').value.trim()||'卡牌画作')};return button}));q('#cardArtEmpty').hidden=!!items.length}
