function referenceButton(asset,selected,kind){const button=document.createElement('button'),image=document.createElement('img'),label=document.createElement('span');button.type='button';button.className=`reference-asset${selected.has(asset.id)?' selected':''}`;button.title='单击选择参考图；双击放大查看';image.src=artFileUrl(asset.id);image.alt='可选参考图';label.textContent=asset.provenance==='user_reference'?(asset.originalName||'上传图'):(asset.targetType==='card'?'关联卡牌':'设定画作');button.append(image,label);button.onclick=event=>{if(event.detail>1){openImageViewer(asset,'参考图');return}selected.has(asset.id)?selected.delete(asset.id):selected.size<10?selected.add(asset.id):showToast('一次最多选择 10 张参考图');renderReferenceAssets(kind)};return button}
