function renderCards(query=cardLibraryQuery){cardLibraryQuery=query;const cards=readCards(),map=keywordMap(),z=query.toLowerCase(),type=q('#cardLibraryType')?.value||'all',rarity=q('#cardLibraryRarity')?.value||'all',filtered=cards.filter(c=>(type==='all'||c.type===type)&&(rarity==='all'||c.rarity===rarity)&&`${c.name} ${c.type} ${WorldforgeCards.typeLabels[c.type]} ${c.rarity} ${WorldforgeCards.rarityLabels[c.rarity]} ${c.rulesText} ${c.flavorText} ${WorldforgeCards.subtypeText(c)} ${c.keywordUsages.map(item=>map.get(item.keywordId)?.name||'').join(' ')} ${c.loreRefs.join(' ')}`.toLowerCase().includes(z)),pageSize=8,pageCount=Math.max(1,Math.ceil(filtered.length/pageSize));cardLibraryPage=Math.min(cardLibraryPage,pageCount);const pageItems=filtered.slice((cardLibraryPage-1)*pageSize,cardLibraryPage*pageSize);q('#cardList').replaceChildren(...pageItems.map(c=>miniCard(c,map)));q('#draftCardCount').textContent=cards.length;q('#savedCardLabel').textContent=`${filtered.length} / ${cards.length} 张`;q('#cardEmpty').hidden=!!cards.length;q('#cardNoResults').hidden=!(cards.length&&!filtered.length);q('#cardPageLabel').textContent=`第 ${cardLibraryPage} / ${pageCount} 页`;q('#cardPagePrev').disabled=cardLibraryPage<=1;q('#cardPageNext').disabled=cardLibraryPage>=pageCount;renderArtworkGallery()}
