function freeAgentMeta(message){const trace=Array.isArray(message.trace)?message.trace:[],notes=[];if(message.toolMode==='native')notes.push(trace.length?`检索资料 ${trace.length} 次 · ${message.rounds||1} 轮`:'直接回答，未检索');else if(message.toolMode==='unavailable')notes.push('当前接口不支持工具调用，已退回单轮问答');if(message.images)notes.push(`附图 ${message.images} 张`);if(message.vision==='unavailable')notes.push('模型接口不接受图片，已移除附图');if(!notes.length&&!trace.length)return null;const wrap=document.createElement('details'),summary=document.createElement('summary');wrap.className='free-trace';summary.textContent=notes.join(' · ');wrap.append(summary);if(trace.length){const list=document.createElement('div');list.className='free-trace-list';list.append(...trace.map(record=>{const row=document.createElement('div'),name=document.createElement('strong'),detail=document.createElement('small');row.className=`free-trace-row${record.ok===false?' failed':''}`;name.textContent=String(record.name||'工具');detail.textContent=`第 ${record.round||1} 轮 · ${record.summary||''}`;row.append(name,detail);return row}));wrap.append(list)}return wrap}
const FREE_ATTACH_LIMIT=4;
let freeAttachmentIds=[];
function renderFreeAttachments(){const query=q('#freeAttachSearch').value.trim().toLowerCase(),items=artAssets.filter(asset=>!query||`${asset.purpose||''} ${asset.targetId||''} ${asset.prompt||''}`.toLowerCase().includes(query)).slice(0,48),tray=q('#freeAttachTray');tray.replaceChildren(...items.map(asset=>{const button=document.createElement('button'),image=document.createElement('img'),caption=document.createElement('small'),selected=freeAttachmentIds.includes(asset.id);button.type='button';button.className=`free-attach-item${selected?' selected':''}`;button.setAttribute('aria-pressed',String(selected));button.title=`${asset.purpose||'concept'} · ${asset.targetId||asset.id}`;image.src=artFileUrl(asset.id);image.alt='';caption.textContent=String(asset.purpose||'concept').slice(0,12);button.append(image,caption);button.onclick=()=>toggleFreeAttachment(asset.id);return button}));q('#freeAttachEmpty').hidden=!!items.length;q('#freeAttachCount').textContent=`${freeAttachmentIds.length} / ${FREE_ATTACH_LIMIT}`}
