function freeContextPreview(message){const wrap=document.createElement('div'),context=message.context,assets=(Array.isArray(message.assets)?message.assets:[]).map(id=>artAssets.find(asset=>asset.id===id)||{id});wrap.className='free-context-preview';if(context){const row=document.createElement('div'),label=document.createElement('span');row.className='free-context-row';label.className='free-context-label';label.textContent='参考资料';row.append(label);if(context.mode==='all'){const chip=document.createElement('span');chip.className='free-context-chip';chip.textContent=`整个资料库 · ${context.total} 条`;row.append(chip)}else{const shown=context.references.slice(0,6);shown.forEach(ref=>{const chip=document.createElement('span');chip.className='free-context-chip';chip.title=`${ref.id} · ${ref.status||''}`;chip.textContent=`${ref.name} · ${LORE_TYPES[ref.type]?.label||ref.type}`;row.append(chip)});if(context.references.length>shown.length){const more=document.createElement('span');more.className='free-context-chip more';more.textContent=`+${context.references.length-shown.length}`;row.append(more)}}if(context.artCount){const art=document.createElement('span');art.className='free-context-chip art';art.textContent=`原画 ${context.artCount} 张`;row.append(art)}wrap.append(row)}if(assets.length){const row=document.createElement('div'),label=document.createElement('span');row.className='free-context-row';label.className='free-context-label';label.textContent=`图片 ${assets.length}`;row.append(label,...assets.map(asset=>{const thumb=document.createElement('button'),image=document.createElement('img');thumb.type='button';thumb.className='free-attach-thumb';thumb.title=asset.id;image.src=artFileUrl(asset.id);image.alt='附加图片';thumb.append(image);thumb.onclick=()=>openImageViewer(asset,asset.purpose||'附加图片');return thumb}));wrap.append(row)}return wrap.children.length?wrap:null}
function renderFreeChat(){const log=q('#freeChatLog');if(!freeMessages.length){const empty=document.createElement('div');empty.className='free-empty';empty.innerHTML='<strong>从任何创作需求开始</strong><p>例如比较三套文明冲突、续写一段场景，或分析某个机制为何无趣。</p>';log.replaceChildren(empty);return}log.replaceChildren(...freeMessages.map(message=>{const item=document.createElement('div'),role=document.createElement('small'),body=document.createElement('div');item.className=`free-message ${message.role}`;role.textContent=message.role==='assistant'?'自由 Agent':'你';body.textContent=message.content;item.append(role,body);if(message.role==='assistant'){const meta=freeAgentMeta(message);if(meta)item.append(meta)}else{const preview=freeContextPreview(message);if(preview)item.append(preview)}return item}));log.scrollTop=log.scrollHeight}
